import React, { useEffect, useState } from "react";
import Header from "../../components/Header/Header";
import Footer from "../../components/Footer/Footer";
import "./result-list-page.css";
import { useNavigate } from "react-router-dom";

type Test = {
  test_id: number;
  created_at: string;
  created_by?: string;
};

type TestData = {
  incomplete_tests: Test[];
  tests_with_pending_results: Test[];
  tests_with_results: Test[];
};

const ResultListPage: React.FC = () => {
  const [testData, setTestData] = useState<TestData>({
    incomplete_tests: [],
    tests_with_pending_results: [],
    tests_with_results: [],
  });
  const [message, setMessage] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("incomplete");
  const navigate = useNavigate();

  useEffect(() => {
    let isMounted = true;

    const fetchTestData = async () => {
      try {
        const rollno = localStorage.getItem("userEmail");
        if (!rollno) {
          if (isMounted) setMessage("Roll number not found. Please log in.");
          return;
        }

        const response = await fetch("http://localhost:5000/resultlist", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ rollno }),
        });

        if (isMounted) {
          if (response.ok) {
            const data: Partial<TestData> = await response.json();
            setTestData({
              incomplete_tests: data.incomplete_tests ?? [],
              tests_with_pending_results: data.tests_with_pending_results ?? [],
              tests_with_results: data.tests_with_results ?? [],
            });
          } else {
            const error = await response.json();
            setMessage(`Error: ${error.error || "Failed to fetch test data."}`);
          }
        }
      } catch (err: any) {
        if (isMounted) setMessage(`Error: ${err.message || "Something went wrong."}`);
      }
    };

    fetchTestData();
    const interval = setInterval(fetchTestData, 5000);

    return () => {
      isMounted = false;
      clearInterval(interval);
    };
  }, []);

  const handleAction = async (testId: number, action: string) => {
    try {
      if (action === "view_result") {
        localStorage.setItem("test_id", testId.toString());
        navigate("/completion-page");
        return;
      } 

      if (action === "check_result") {
        const response = await fetch("http://localhost:5000/check_result", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "Connection": "keep-alive"
          },
          body: JSON.stringify({ testId }),
        });

        if (response.status === 426) {
          alert("Server requires an upgrade. Try using HTTPS instead.");
          return;
        }

        const data = await response.json();

        if (response.ok) {
          alert("Results are being processed. Try again after some time.");
          window.location.reload();
        } else {
          alert(`Error: ${data.error || "Failed to process results."}`);
        }
      }
    } catch (err: any) {
      setMessage(`Error: ${err.message || "Something went wrong."}`);
    }
  };

  const renderTests = () => {
    const testMapping = {
      incomplete: { tests: testData.incomplete_tests, label: "Resume", action: "resume" },
      pending: { tests: testData.tests_with_pending_results, label: "Check Result", action: "check_result" },
      results: { tests: testData.tests_with_results, label: "View Result", action: "view_result" }
    };

    const { tests, label, action } = testMapping[activeTab as keyof typeof testMapping];

    return tests.length > 0 ? (
      tests.map((test) => (
        <div key={test.test_id} className="test-item">
          <span>Test ID: {test.test_id}</span>
          <span>Created At: {test.created_at}</span>
          <button onClick={() => handleAction(test.test_id, action)} className="action-button">
            {label}
          </button>
        </div>
      ))
    ) : (
      <p>No {activeTab} tests available.</p>
    );
  };

  return (
    <div className="App">
      <Header />
      <div className="result-container">
        <div className="main-content">
          <h2>Test Status</h2>
          {message && <p className="feedback-message">{message}</p>}

          <div className="tab-buttons">
            {['incomplete', 'pending', 'results'].map(tab => (
              <button 
                key={tab}
                className={`tab-button ${activeTab === tab ? "active" : ""}`} 
                onClick={() => setActiveTab(tab)}
              >
                {tab.charAt(0).toUpperCase() + tab.slice(1)} Tests
              </button>
            ))}
          </div>

          <div className="test-list">{renderTests()}</div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ResultListPage;
